import axios from 'axios';
import ncp from 'copy-paste';
import { getLoggedInUser } from '../utils/config.util';
import { MKDB_BASE_URL } from '../utils/env.util';
import logger from '../utils/logger.util';
import login from './login';
import logout from './logout';
import selectRegion from './select-region';

const createDb = async (dbname: string) => {
  let userInfo = await getLoggedInUser();
  if (!userInfo) {
    await login();
    userInfo = await getLoggedInUser();
    if (!userInfo)
      return logger.log('you must be logged in to create a database');
  }
  let region = userInfo.defaultRegion || (await selectRegion(true))?.region;

  console.log('region', region);

  const res = await axios
    .post(
      `${MKDB_BASE_URL}/api/databases`,
      { name: dbname, region },
      {
        headers: {
          Authorization: userInfo.apiToken,
          'Content-Type': 'application/json',
        },
      },
    )
    .catch((error) => {
      // TODO:  if user's token has expired, we should gracefully re-login, not really handling 401 well right now
      logger.dev.log('error:', [
        error.response.status,
        error.response.statusText,
      ]);
      if (error.response.status === 401) {
        logger.log(
          'looks like your session has expired. please login again.\n\nmkdb login',
        );
        logout(true);
        logger.log('error', error.response.data.message);
      } else if (error.response.status === 402) {
        logger.log(`db limit exceeded`);
      }

      return undefined;
    });

  logger.dev.log('res', res?.data);

  if (res?.data) {
    const logConnString = (wasCopied: boolean) =>
      logger.log(
        `\nconnection string${wasCopied ? ' (copied to clipboard)' : ''}:\n${
          res.data.connectionString
        }`,
      );

    logger.log(res.data.message);
    try {
      ncp.copy(res.data.connectionString);
      logConnString(true);
    } catch (err) {
      logConnString(false);
    }
  }
  return null;
};

export default createDb;
